/** Observes this entrant's scores and validates submissions against completed stays. */
@Composable
fun CampsiteRatings(
    campsiteId: String,
    entrantId: String,
    reservations: List<Reservation>,
    repository: CampsiteRatingStore = remember { FirestoreCampsiteRatingRepository() },
    clock: () -> Long = System::currentTimeMillis,
) {
    var ratings by remember(campsiteId, entrantId) { mutableStateOf<List<Rating>?>(null) }
    var loadFailed by remember(campsiteId, entrantId) { mutableStateOf(false) }
    var retry by remember(campsiteId, entrantId) { mutableIntStateOf(0) }
    var submitting by remember(campsiteId, entrantId) { mutableStateOf<String?>(null) }
    var message by remember(campsiteId, entrantId) { mutableStateOf<String?>(null) }
    var now by remember(campsiteId, entrantId) { mutableLongStateOf(clock()) }
    val scope = rememberCoroutineScope()
    val controller = remember(repository, clock) { CampsiteRatingController(repository, clock) }

    LaunchedEffect(campsiteId, entrantId, repository, retry) {
        loadFailed = false
        ratings = null
        try {
            repository.observeRatings(campsiteId, entrantId).collect { ratings = it }
        } catch (cancelled: CancellationException) {
            throw cancelled
        } catch (_: Exception) {
            ratings = null
            loadFailed = true
        }
    }
    LaunchedEffect(clock) {
        while (true) {
            now = clock()
            delay(60_000L)
        }
    }

    CampsiteRatingsScreen(
        stays = rateableStays(reservations, campsiteId, entrantId, now),
        ratings = ratings.orEmpty(),
        loading = ratings == null && !loadFailed,
        loadFailed = loadFailed,
        submitting = submitting,
        statusMessage = message,
        onRetry = { retry++ },
        onSubmit = { stay, score ->
            if (submitting == null) {
                val updating = ratings.orEmpty().any { it.reservationId == stay.id }
                submitting = stay.id
                message = null
                scope.launch {
                    try {
                        controller.submit(campsiteId, entrantId, stay, score)
                        message = if (updating) "Rating updated." else "Rating saved."
                    } catch (cancelled: CancellationException) {
                        throw cancelled
                    } catch (_: Exception) {
                        message = "Could not save your rating. Please try again."
                    } finally {
                        submitting = null
                    }
                }
            }
        },
    )
}

/** Presentation separated from persistence so rating interactions can be tested without Firebase. */
@Composable
fun CampsiteRatingsScreen(
    stays: List<Reservation>,
    ratings: List<Rating>,
    loading: Boolean = false,
    loadFailed: Boolean = false,
    submitting: String? = null,
    statusMessage: String? = null,
    onRetry: () -> Unit = {},
    onSubmit: (Reservation, Int) -> Unit,
) {
    Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Text("Rate your stays", style = MaterialTheme.typography.titleLarge)
        when {
            loadFailed -> {
                Text("Could not load your ratings.")
                TextButton(onClick = onRetry, modifier = Modifier.testTag("retryStayRatings")) { Text("Retry ratings") }
            }
            loading -> Text("Loading your ratings…")
            stays.isEmpty() -> Text("You can rate this campsite after a completed stay.")
            else -> stays.forEach { stay ->
                key(stay.id) {
                    StayRatingCard(
                        stay = stay,
                        rating = ratings.firstOrNull {
                            it.reservationId == stay.id && it.campsiteId == stay.campsiteId && it.entrantId == stay.entrantId
                        },
                        enabled = submitting == null,
                        saving = submitting == stay.id,
                        onSubmit = { onSubmit(stay, it) },
                    )
                }
            }
        }
        statusMessage?.let { Text(it, modifier = Modifier.testTag("stayRatingStatus")) }
    }
}

/** Score chips are labeled numerically for touch, keyboard and accessibility users. */
@Composable
private fun StayRatingCard(
    stay: Reservation,
    rating: Rating?,
    enabled: Boolean,
    saving: Boolean,
    onSubmit: (Int) -> Unit,
) {
    var selected by rememberSaveable(stay.id, rating?.score) { mutableIntStateOf(rating?.score ?: 0) }
    Card(Modifier.fillMaxWidth().testTag("stayRating-${stay.id}")) {
        Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Text("Stay: ${formatDateRange(stay.startDate, stay.endDate)}")
            if (rating != null) Text("Your rating: ${rating.score} / 5")
            Text("Choose a score from 1 (lowest) to 5 (highest).")
            Row(horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                (1..5).forEach { score ->
                    FilterChip(
                        selected = selected == score,
                        enabled = enabled,
                        onClick = { selected = score },
                        label = { Text("$score") },
                        modifier = Modifier.testTag("stayRatingScore-${stay.id}-$score"),
                    )
                }
            }
            Button(
                onClick = { onSubmit(selected) },
                enabled = enabled && selected in 1..5 && selected != rating?.score,
                modifier = Modifier.testTag("saveStayRating-${stay.id}"),
            ) {
                Text(when {
                    saving -> "Saving rating…"
                    rating != null -> "Update rating"
                    else -> "Submit rating"
                })
            }
        }
    }
}
